import { BooleanColumn, ReferenceColumn, ScriptColumn, StringColumn, Table, ListColumn } from '../../db'

export const sys_ws_operation = Table({
    name: 'sys_ws_operation',
    extends: 'sys_metadata',
    schema: {
        name: StringColumn({}),
        active: BooleanColumn({}),
        consumes: StringColumn({}),
        consumes_customized: BooleanColumn({}),
        enforce_acl: ListColumn({ referenceTable: 'sys_security_acl' }),
        http_method: StringColumn({}),
        operation_script: ScriptColumn({}),
        operation_uri: StringColumn({}),
        produces: StringColumn({}),
        produces_customized: BooleanColumn({}),
        relative_path: StringColumn({}),
        requires_acl_authorization: BooleanColumn({}),
        requires_authentication: BooleanColumn({}),
        requires_snc_internal_role: BooleanColumn({}),
        short_description: StringColumn({}),
        request_example: StringColumn({}),
        web_service_definition: ReferenceColumn({ referenceTable: 'sys_ws_definition' }),
        web_service_version: ReferenceColumn({ referenceTable: 'sys_ws_version' }),
    },
})
